 "content": "def transform(grid):
    from collections import deque
    h, w = len(grid), len(grid[0])
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color in (0, 6, 7) or (r, c) in seen:
                continue
            q = deque([(r,c)])
            seen.add((r,c))
            cells=[]
            while q:
                y,x=q.popleft(); cells.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy,xx=y+dy,x+dx
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); q.append((yy,xx))
            comps.append((len(cells),color))
    color=max(comps)[1]
    return [[color]*3 for _ in range(3)]
